package dev.veltraph.client.hydra;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class SourceFloorProducerTest {
    final Object p=new Object(),w=new Object(),c=new Object(),o=new Object();
    SourceFloorProducer.Scope scope(long generation,boolean enabled){return new SourceFloorProducer.Scope(p,w,c,o,generation,enabled);}
    void offer(SourceFloorProducer producer,int count,long tick){for(int i=0;i<count;i++)assertTrue(producer.accept(scope(1,true),true,false,0,70,0,i%10,70,0,tick));}
    boolean evaluate(SourceFloorProducer d,long firstTick,long now){boolean result=false;for(int i=0;i<8;i++)result=d.tick(scope(1,true),firstTick+i,now);return result;}
    @Test void sourceWindowThresholdAndExecutionTimestamp(){var d=new SourceFloorProducer();offer(d,11,5);assertFalse(d.tick(scope(1,true),5,1000));assertFalse(d.tick(scope(1,true),6,2000));for(int i=0;i<5;i++)assertFalse(d.tick(scope(1,true),7+i,2000));assertTrue(d.tick(scope(1,true),12,2450));assertFalse(evaluate(d,13,2451));}
    @Test void sourceCountsDistinctDeliveredEventsWithoutCoordinateDedup(){var d=new SourceFloorProducer();for(int i=0;i<11;i++)d.accept(scope(1,true),true,false,0,70,0,0,70,0,5);assertTrue(evaluate(d,6,100));assertEquals(11,d.count());}
    @Test void oldBedrockOrOtherIncomingBlockDoesNotSchedule(){var d=new SourceFloorProducer();assertFalse(d.accept(scope(1,true),true,true,0,70,0,0,70,0,1));assertFalse(d.accept(scope(1,true),false,false,0,70,0,0,70,0,1));assertEquals(0,d.pendingCount());}
    @Test void strictIntegerCornerThreeDimensionalRange(){var d=new SourceFloorProducer();assertFalse(d.accept(scope(1,true),true,false,0,70,0,18,70,0,1));assertTrue(d.accept(scope(1,true),true,false,.001,70,0,18,70,0,1));assertFalse(d.accept(scope(1,true),true,false,0,70,0,0,88,0,1));}
    @Test void pendingCallbackCannotCrossNativeOrOwnerEpoch(){for(var next:new SourceFloorProducer.Scope[]{new SourceFloorProducer.Scope(new Object(),w,c,o,1,true),new SourceFloorProducer.Scope(p,new Object(),c,o,1,true),new SourceFloorProducer.Scope(p,w,new Object(),o,1,true),new SourceFloorProducer.Scope(p,w,c,new Object(),1,true),scope(2,true)}){var d=new SourceFloorProducer();offer(d,11,1);assertFalse(d.tick(next,2,100));assertEquals(0,d.count());assertEquals(0,d.pendingCount());}}
    @Test void disabledThenReenabledDoesNotCarryDelayedWork(){var d=new SourceFloorProducer();offer(d,11,1);assertFalse(d.tick(scope(1,false),2,100));assertFalse(d.tick(scope(2,true),3,101));assertEquals(0,d.count());}
    @Test void clockOrTickRollbackClearsQueuedAndCountedEvents(){var d=new SourceFloorProducer();offer(d,11,5);assertTrue(evaluate(d,6,100));assertFalse(d.tick(scope(1,true),5,99));assertEquals(0,d.count());}
    @Test void explicitStopClearsBothPendingAndCount(){var d=new SourceFloorProducer();offer(d,11,1);d.clear();assertFalse(d.tick(scope(1,true),2,100));assertEquals(0,d.pendingCount());}
    @Test void tenAtThresholdDoesNotDetectAfterEighthEvaluation(){var d=new SourceFloorProducer();offer(d,10,1);assertFalse(evaluate(d,2,100));assertTrue(d.receipt().evaluated());assertEquals(8,d.receipt().invocation());assertEquals(10,d.receipt().count());}
    @Test void evaluationIsEighthEligibleCallWithIndependentPerCallbackClock(){var d=new SourceFloorProducer();offer(d,11,1);var clock=new java.util.concurrent.atomic.AtomicLong(100);for(int i=0;i<7;i++)assertFalse(d.tick(scope(1,true),2+i,clock::getAndIncrement));assertEquals(11,d.count());assertTrue(d.tick(scope(1,true),9,clock::getAndIncrement));assertTrue(clock.get()>=119);}
    @Test void originalClearCountDoesNotCancelAlreadyQueuedCallback(){var original=new SourceBedrockFloorEvents();for(int i=0;i<11;i++)original.accept(new SourceBedrockFloorEvents.Event(true,true,false,0,70,0,0,70,0));original.clearCount();original.nextTick(100);assertTrue(original.detected(100));}
    @Test void nullOwnerCannotAuthorizeNativeEvent(){var d=new SourceFloorProducer();assertFalse(d.accept(new SourceFloorProducer.Scope(p,w,c,null,1,true),true,false,0,70,0,0,70,0,1));assertEquals(0,d.pendingCount());}
    @Test void nativeContextMustBeCompleteForAuthorizedEvent(){for(var scope:new SourceFloorProducer.Scope[]{new SourceFloorProducer.Scope(null,w,c,o,1,true),new SourceFloorProducer.Scope(p,null,c,o,1,true),new SourceFloorProducer.Scope(p,w,null,o,1,true)}){var d=new SourceFloorProducer();assertFalse(d.accept(scope,true,false,0,70,0,0,70,0,1));}}
    @Test void externalVerifiedOwnerOverridesStillEnabledParent(){var parent=new Object();var healer=new Object();assertSame(healer,SourceFloorCustody.select(true,healer,parent));}
    @Test void unverifiedExternalOwnerNeverFallsBackToParent(){assertNull(SourceFloorCustody.select(true,null,new Object()));}
    @Test void registeredParentUsedOnlyWhenExternalInactive(){var parent=new Object();assertSame(parent,SourceFloorCustody.select(false,new Object(),parent));}
    @Test void appendReportingFailureProcessesEveryActualCallbackAndKeepsTrueResult(){var d=new SourceFloorProducer();offer(d,11,1);d.reportProbe(phase->{if(phase.equals("append"))throw new AssertionError("append diagnostic allocation");});assertTrue(evaluate(d,2,100));assertEquals(0,d.pendingCount());assertEquals(11,d.count());assertEquals(11,d.receipt().appended());}
    @Test void receiptAndDetectedCopyFailuresCannotSuppressComputedTrue(){for(String failedPhase:new String[]{"receipt","detected-copy"}){var d=new SourceFloorProducer();offer(d,11,1);d.reportProbe(phase->{if(phase.equals(failedPhase))throw new IllegalStateException("diagnostic failure");});assertTrue(evaluate(d,2,100));assertEquals(0,d.pendingCount());assertEquals(11,d.count());assertNull(d.receipt());d.reportProbe(phase->{});assertTrue(evaluate(d,10,101));assertEquals(11,d.receipt().count());}}
}
